use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let n = input["n"].as_u64().unwrap();
    let start = input["start"].as_u64().unwrap();
    let target = input["target"].as_u64().unwrap();
    let edges = input["edges"].as_array().unwrap();
    let mut dist = vec![i64::MAX; n];
    dist[start as usize] = 0;

    for edge in edges {
        let u = edge[0].as_u64().unwrap();
        let v = edge[1].as_u64().unwrap();
        dist[v as usize] = dist[u as usize].min(dist[v as usize]);
    }

    if dist[target as usize] == i64::MAX {
        Value::from(-1)
    } else {
        Value::from(dist[target as usize])
    }
}
